    # TODO：替换占位返回值
    return 0

lab.solution:
def reshape(values, rows, cols):
    if rows < 0 or cols < 0 or rows * cols != len(values):
        raise ValueError("shape mismatch")
    return [values[i*cols:(i+1)*cols] for i in range(rows)]

