def matvec(matrix, vector):
    # TODO：替换占位返回值
    return 0

lab.solution:
def matvec(matrix, vector):
    if not matrix or any(len(row)!=len(vector) for row in matrix):
        return -1
    return [sum(x*y for x,y in zip(row,vector)) for row in matrix]

