def classify(x, weights, bias):
    # TODO：替换占位返回值
    return 0

lab.solution:
def classify(x, weights, bias):
    import math
    z=sum(a*b for a,b in zip(x,weights))+bias
    p=1/(1+math.exp(-z)) if z>=0 else math.exp(z)/(1+math.exp(z))
    return int(p>=0.5)

lab.starter:
def knn(points, labels, query, k):
    # TODO：替换占位返回值
    return 0

lab.solution:
def knn(points, labels, query, k):
    if not 1<=k<=len(points):
        raise ValueError("invalid k")
    indices=sorted(range(len(points)),key=lambda i:(abs(points[i]-query),i))[:k]
    votes=[labels[i] for i in indices]
    return min(set(votes),key=lambda label:(-votes.count(label),label))

lab.starter:
def kmeans_step(points, centers):
    # TODO：替换占位返回值
    return 0

lab.solution:
def kmeans_step(points, centers):
    groups=[[] for _ in centers]
    for p in points:
        i=min(range(len(centers)),key=lambda i:abs(p-centers[i]))
        groups[i].append(p)
    return [sum(g)/len(g) if g else centers[i] for i,g in enumerate(groups)]

lab.starter:
def entropy(labels):
    # TODO：替换占位返回值
    return 0

lab.solution:
def entropy(labels):
    import math
    if not labels:
        return 0.0
    probs=[labels.count(v)/len(labels) for v in set(labels)]
    return -sum(p*math.log2(p) for p in probs)

