lab.solution:
def split_data(x, y, test_indices):
    selected=set(test_indices)
    train=[i for i in range(len(x)) if i not in selected]
    test=[i for i in range(len(x)) if i in selected]
    return ([x[i] for i in train],[x[i] for i in test],[y[i] for i in train],[y[i] for i in test])

