    # TODO：替换占位返回值
    return 0

lab.solution:
def ridge_loss(predictions, targets, weights, alpha):
    mse=sum((p-t)**2 for p,t in zip(predictions,targets))/len(targets)
    return mse+alpha*sum(w*w for w in weights)
